/* Constructeur de payoff : profit d'une stratégie d'options à l'échéance */
(function () {
  var svg = document.getElementById("st-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  // Chaque stratégie : liste de jambes { t:'c'|'p'|'s', p:position, K:strike, pr:prime }
  var STRATS = [
    { key:"bullcall",  names:{fr:"Bull call spread",en:"Bull call spread",nl:"Bull call spread"},
      legs:[{t:"c",p:1,K:48,pr:3.0},{t:"c",p:-1,K:52,pr:1.2}] },
    { key:"bearput",   names:{fr:"Bear put spread",en:"Bear put spread",nl:"Bear put spread"},
      legs:[{t:"p",p:1,K:52,pr:3.0},{t:"p",p:-1,K:48,pr:1.2}] },
    { key:"straddle",  names:{fr:"Straddle (long)",en:"Straddle (long)",nl:"Straddle (long)"},
      legs:[{t:"c",p:1,K:50,pr:2.12},{t:"p",p:1,K:50,pr:1.87}] },
    { key:"strangle",  names:{fr:"Strangle (long)",en:"Strangle (long)",nl:"Strangle (long)"},
      legs:[{t:"p",p:1,K:45,pr:0.52},{t:"c",p:1,K:55,pr:0.32}] },
    { key:"butterfly", names:{fr:"Butterfly (long)",en:"Butterfly (long)",nl:"Butterfly (long)"},
      legs:[{t:"c",p:1,K:45,pr:6.0},{t:"c",p:-2,K:50,pr:2.5},{t:"c",p:1,K:55,pr:1.0}] },
    { key:"coveredcall", names:{fr:"Covered call",en:"Covered call",nl:"Covered call"},
      legs:[{t:"s",p:1,K:50,pr:0},{t:"c",p:-1,K:52,pr:1.5}] }
  ];

  function profit(S, legs){
    var t=0;
    for (var i=0;i<legs.length;i++){
      var L=legs[i];
      if (L.t==="c") t += L.p*(Math.max(S-L.K,0) - L.pr);
      else if (L.t==="p") t += L.p*(Math.max(L.K-S,0) - L.pr);
      else if (L.t==="s") t += L.p*(S - L.K);
    }
    return t;
  }
  function unl(){ var a=al(); return a==="en"?"unlimited":(a==="nl"?"onbeperkt":"illimité"); }
  function none(){ var a=al(); return a==="en"?"none":(a==="nl"?"geen":"aucun"); }

  function draw(){
    var si=Math.round(v("st-strat")), ST=v("st-s");
    var strat=STRATS[si];
    setT("st-strat-o", strat.names[al()]||strat.names.fr);
    setT("st-s-o", ST.toFixed(1));
    setT("st-name", strat.names[al()]||strat.names.fr);

    // balayage pour breakevens / min / max
    var lo=0, hi=100, step=0.25, prev=null, prevP=null, bes=[];
    var minP=Infinity, maxP=-Infinity;
    for (var S=lo; S<=hi+1e-9; S+=step){
      var P=profit(S, strat.legs);
      if (P<minP) minP=P; if (P>maxP) maxP=P;
      if (prev!==null && ((prevP<0&&P>=0)||(prevP>0&&P<=0)) && prevP!==P){
        var bx = prev + (0-prevP)*(S-prev)/(P-prevP);
        bes.push(bx);
      }
      prev=S; prevP=P;
    }
    // pente aux bords pour détecter l'illimité
    var slopeR = profit(hi,strat.legs)-profit(hi-step,strat.legs);
    var slopeL = profit(lo,strat.legs)-profit(lo+step,strat.legs); // vers la gauche
    var gainUnl = slopeR>0.02;
    var lossUnl = slopeR<-0.02;

    setT("st-be", bes.length? bes.map(function(x){return x.toFixed(1);}).join(" / ") : none());
    setT("st-max", gainUnl? unl() : ("+"+maxP.toFixed(2)));
    setT("st-min", lossUnl? ("-"+unl()) : (minP.toFixed(2)));
    var atP=profit(ST, strat.legs);
    setT("st-at", (atP>=0?"+":"")+atP.toFixed(2));

    // échelle graphe
    var W=520,H=300,L=46,R0=16,T0=16,B=34, pw=W-L-R0, ph=H-T0-B;
    var xlo=30, xhi=70;
    var ys=[]; for (var s2=xlo;s2<=xhi;s2+=0.5) ys.push(profit(s2,strat.legs));
    var ymin=Math.min.apply(null,ys), ymax=Math.max.apply(null,ys);
    var pad=(ymax-ymin)*0.18||1; ymin-=pad; ymax+=pad;
    if (ymin>0) ymin=-pad; if (ymax<0) ymax=pad;
    function px(s){ return L + (s-xlo)/(xhi-xlo)*pw; }
    function py(val){ return T0 + (1-(val-ymin)/(ymax-ymin))*ph; }

    var g="";
    // zone gain/perte : ligne zéro
    var y0=py(0);
    g+='<rect x="'+L+'" y="'+T0+'" width="'+pw+'" height="'+(y0-T0).toFixed(1)+'" fill="var(--teal)" opacity="0.06"/>';
    g+='<rect x="'+L+'" y="'+y0.toFixed(1)+'" width="'+pw+'" height="'+(T0+ph-y0).toFixed(1)+'" fill="var(--crimson)" opacity="0.06"/>';
    g+='<line x1="'+L+'" y1="'+y0.toFixed(1)+'" x2="'+(L+pw)+'" y2="'+y0.toFixed(1)+'" stroke="var(--ink-mute)" stroke-width="1.1" stroke-dasharray="4 4"/>';
    // strikes (repères verticaux légers)
    var seen={};
    strat.legs.forEach(function(L2){ if(L2.t!=="s" && !seen[L2.K] && L2.K>=xlo && L2.K<=xhi){ seen[L2.K]=1;
      g+='<line x1="'+px(L2.K).toFixed(1)+'" y1="'+T0+'" x2="'+px(L2.K).toFixed(1)+'" y2="'+(T0+ph)+'" stroke="var(--ink-mute)" stroke-width="0.7" stroke-dasharray="2 4" opacity="0.6"/>';
    }});
    // courbe profit
    var d="";
    for (var i=0;i<=160;i++){ var s=xlo+(xhi-xlo)*i/160; d+=(i===0?"M ":" L ")+px(s).toFixed(1)+","+py(profit(s,strat.legs)).toFixed(1); }
    g+='<path d="'+d+'" fill="none" stroke="var(--teal)" stroke-width="2.6"/>';
    // marqueur Sₜ
    var mp=profit(ST,strat.legs);
    g+='<line x1="'+px(ST).toFixed(1)+'" y1="'+T0+'" x2="'+px(ST).toFixed(1)+'" y2="'+(T0+ph)+'" stroke="var(--gold)" stroke-width="1.4"/>';
    g+='<circle cx="'+px(ST).toFixed(1)+'" cy="'+py(mp).toFixed(1)+'" r="4.5" fill="var(--gold)"/>';
    // axes
    g+='<line class="axis" x1="'+L+'" y1="'+(T0+ph)+'" x2="'+(L+pw)+'" y2="'+(T0+ph)+'"/>';
    g+='<line class="axis" x1="'+L+'" y1="'+T0+'" x2="'+L+'" y2="'+(T0+ph)+'"/>';
    // libellés axes
    var xl = al()==="en"?"final price Sₜ":(al()==="nl"?"finale prijs Sₜ":"prix final Sₜ");
    var yl = al()==="en"?"profit":(al()==="nl"?"winst":"profit");
    g+='<text class="lab" x="'+(L+pw)+'" y="'+(T0+ph+16)+'" text-anchor="end">'+xl+'</text>';
    g+='<text class="lab" x="'+L+'" y="'+(T0-4)+'" text-anchor="start">'+yl+'</text>';
    [40,50,60,70].forEach(function(t){ if(t>=xlo&&t<=xhi){ g+='<text class="tick" x="'+px(t).toFixed(1)+'" y="'+(T0+ph+14)+'" text-anchor="middle">'+t+'</text>'; }});
    g+='<text class="tick" x="'+(L-6)+'" y="'+(y0+3).toFixed(1)+'" text-anchor="end">0</text>';
    svg.innerHTML=g;
  }
  ["st-strat","st-s"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
